exercise3.solutionCode:
schedule = [("Python Basics", "Room A")]

name2 = input()
room2 = input()
name3 = input()
room3 = input()

schedule.append((name2, room2))
schedule.append((name3, room3))

for name, room in schedule:
    print(f"{name} — {room}")

room_lookup = {}
for name, room in schedule:
    room_lookup[name] = room

requested = input()
print(room_lookup[requested])

room_sessions = {}
for name, room in schedule:
    if room in room_sessions:
        room_sessions[room].append(name)
    else:
        room_sessions[room] = [name]

room_query = input()
print(room_sessions[room_query])
